SELECT row_number() over () AS _uid_,* FROM (WITH district_stats AS (     SELECT         d.district_id,         COUNT(p.poi_id) AS poi_count,         COUNT(DISTINCT p.category_id) AS category_count     FROM bj_life.district d     LEFT JOIN bj_life.service_poi p       ON p.district_id = d.district_id     GROUP BY d.district_id ) SELECT     d.district_id AS objectid,     d.district_name,     s.poi_count,     s.category_count,      ROUND(         s.category_count::numeric / 8,         2     ) AS completeness,      COALESCE(         (             SELECT STRING_AGG(                 c.service_class_name,                 '、'                 ORDER BY c.category_id             )             FROM bj_life.service_category c             WHERE NOT EXISTS (                 SELECT 1                 FROM bj_life.service_poi p2                 WHERE p2.district_id = d.district_id                   AND p2.category_id = c.category_id             )         ),         '无'     ) AS missing_categories,      d.geom  FROM bj_life.district d JOIN district_stats s   ON d.district_id = s.district_id
) AS _subq_1_
